ALTER TABLE public.members DROP CONSTRAINT members_status_check;
ALTER TABLE public.members ADD CONSTRAINT members_status_check CHECK (status IN ('in_asteptare','activ','aprobat','suspendat','retras'));
CREATE OR REPLACE FUNCTION public.portal_access(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin_national') OR public.has_role(_user_id,'admin_filiala') OR public.has_role(_user_id,'editor') OR public.has_role(_user_id,'coordonator_voluntari') OR EXISTS (SELECT 1 FROM public.members m JOIN auth.users u ON u.id=_user_id WHERE lower(m.email)=lower(u.email) AND m.status IN ('aprobat','activ')); $$;
CREATE FUNCTION public.portal_branch() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(public.user_branch(auth.uid()), (SELECT m.branch_id FROM public.members m JOIN auth.users u ON u.id=auth.uid() WHERE lower(m.email)=lower(u.email) AND m.status IN ('aprobat','activ') ORDER BY m.created_at DESC LIMIT 1)); $$;
REVOKE ALL ON FUNCTION public.portal_branch() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.portal_branch() TO authenticated;
CREATE FUNCTION public.my_member_card() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.portal_access(auth.uid()) THEN RAISE EXCEPTION 'Acces interzis'; END IF; SELECT jsonb_build_object('id',m.id,'full_name',m.full_name,'status',m.status,'joined_at',m.joined_at,'branch',b.name,'dues',COALESCE((SELECT jsonb_agg(jsonb_build_object('year',d.year,'status',d.status,'amount',d.amount,'paid_at',d.paid_at)) FROM public.dues d WHERE d.member_id=m.id AND d.year=EXTRACT(YEAR FROM CURRENT_DATE)::integer),'[]'::jsonb)) INTO result FROM public.members m JOIN auth.users u ON u.id=auth.uid() LEFT JOIN public.branches b ON b.id=m.branch_id WHERE lower(m.email)=lower(u.email) AND m.status IN ('aprobat','activ') ORDER BY m.created_at DESC LIMIT 1; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.my_member_card() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_member_card() TO authenticated;
ALTER TABLE public.portal_documents ADD COLUMN kind text NOT NULL DEFAULT 'procedura' CHECK (kind IN ('procedura','anunt'));
ALTER TABLE public.forum_threads ADD COLUMN category text NOT NULL DEFAULT 'general' CHECK (category IN ('general','organizare','initiative','evenimente'));
ALTER TABLE public.forum_threads ADD COLUMN branch_id uuid REFERENCES public.branches(id);
CREATE INDEX forum_threads_branch_idx ON public.forum_threads(branch_id,created_at DESC);
DROP POLICY "members read threads" ON public.forum_threads;
CREATE POLICY "members read threads" ON public.forum_threads FOR SELECT TO authenticated USING (public.portal_access(auth.uid()) AND (branch_id IS NULL OR branch_id=public.portal_branch() OR public.has_role(auth.uid(),'admin_national')));
DROP POLICY "members create threads" ON public.forum_threads;
CREATE POLICY "members create threads" ON public.forum_threads FOR INSERT TO authenticated WITH CHECK (public.portal_access(auth.uid()) AND author_id=auth.uid() AND (branch_id IS NULL OR branch_id=public.portal_branch() OR public.has_role(auth.uid(),'admin_national')) AND locked=false);
CREATE FUNCTION public.guard_forum_moderation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.portal_access(auth.uid()) THEN RAISE EXCEPTION 'Acces interzis'; END IF; IF TG_TABLE_NAME='forum_threads' THEN IF NEW.author_id<>OLD.author_id OR NEW.branch_id IS DISTINCT FROM OLD.branch_id THEN RAISE EXCEPTION 'Autorul și filiala nu pot fi schimbate'; END IF; IF NEW.locked IS DISTINCT FROM OLD.locked AND NOT (public.has_role(auth.uid(),'admin_national') OR public.has_role(auth.uid(),'editor') OR (public.has_role(auth.uid(),'admin_filiala') AND OLD.branch_id=public.portal_branch())) THEN RAISE EXCEPTION 'Doar moderatorii pot închide subiecte'; END IF; ELSE IF NEW.author_id<>OLD.author_id OR NEW.thread_id<>OLD.thread_id THEN RAISE EXCEPTION 'Autorul și subiectul nu pot fi schimbate'; END IF; IF NEW.hidden IS DISTINCT FROM OLD.hidden AND NOT (public.has_role(auth.uid(),'admin_national') OR public.has_role(auth.uid(),'editor') OR (public.has_role(auth.uid(),'admin_filiala') AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=OLD.thread_id AND t.branch_id=public.portal_branch()))) THEN RAISE EXCEPTION 'Doar moderatorii pot ascunde răspunsuri'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_forum_thread BEFORE UPDATE ON public.forum_threads FOR EACH ROW EXECUTE FUNCTION public.guard_forum_moderation();
CREATE TRIGGER guard_forum_post BEFORE UPDATE ON public.forum_posts FOR EACH ROW EXECUTE FUNCTION public.guard_forum_moderation();
DROP POLICY "members read visible posts" ON public.forum_posts;
CREATE POLICY "members read visible posts" ON public.forum_posts FOR SELECT TO authenticated USING (public.portal_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=thread_id) AND (NOT hidden OR author_id=auth.uid() OR public.has_role(auth.uid(),'admin_national') OR public.has_role(auth.uid(),'editor') OR public.has_role(auth.uid(),'admin_filiala')));
DROP POLICY "members create posts" ON public.forum_posts;
CREATE POLICY "members create posts" ON public.forum_posts FOR INSERT TO authenticated WITH CHECK (public.portal_access(auth.uid()) AND author_id=auth.uid() AND hidden=false AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=thread_id AND NOT t.locked));
CREATE TABLE public.forum_likes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),thread_id uuid NOT NULL REFERENCES public.forum_threads(id) ON DELETE CASCADE,user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(thread_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.forum_likes TO authenticated;
GRANT ALL ON public.forum_likes TO service_role;
ALTER TABLE public.forum_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "portal reads likes" ON public.forum_likes FOR SELECT TO authenticated USING (public.portal_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=thread_id));
CREATE POLICY "portal adds own like" ON public.forum_likes FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND public.portal_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=thread_id));
CREATE POLICY "portal removes own like" ON public.forum_likes FOR DELETE TO authenticated USING (user_id=auth.uid() AND public.portal_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.forum_threads t WHERE t.id=thread_id));
DROP POLICY "members read internal events" ON public.internal_events;
CREATE POLICY "members read internal events" ON public.internal_events FOR SELECT TO authenticated USING (public.portal_access(auth.uid()) AND (branch_id IS NULL OR branch_id=public.portal_branch() OR public.has_role(auth.uid(),'admin_national')));
DROP POLICY "members read visible documents" ON public.portal_documents;
CREATE POLICY "members read visible documents" ON public.portal_documents FOR SELECT TO authenticated USING (public.portal_access(auth.uid()) AND (branch_id IS NULL OR branch_id=public.portal_branch() OR public.has_role(auth.uid(),'admin_national')) AND (min_role='membru' OR (min_role='staff' AND (public.has_role(auth.uid(),'admin_national') OR public.has_role(auth.uid(),'admin_filiala') OR public.has_role(auth.uid(),'editor') OR public.has_role(auth.uid(),'coordonator_voluntari'))) OR (min_role='admin' AND (public.has_role(auth.uid(),'admin_national') OR public.has_role(auth.uid(),'admin_filiala')))));
CREATE FUNCTION public.crm_bulk_change(_table text,_ids uuid[],_field text,_value text) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE n integer; BEGIN IF cardinality(_ids) IS NULL OR cardinality(_ids)<1 OR cardinality(_ids)>100 THEN RAISE EXCEPTION 'Selectează între 1 și 100 de înregistrări'; END IF; IF _table NOT IN ('members','volunteers','contacts','tasks') OR _field NOT IN ('status','tags','branch_id') OR (_field='tags' AND _table<>'contacts') OR (_field='status' AND _table='contacts') OR (_field='branch_id' AND _table='tasks') THEN RAISE EXCEPTION 'Acțiune nepermisă'; END IF; IF NOT (public.has_role(auth.uid(),'admin_national') OR public.has_role(auth.uid(),'admin_filiala') OR (_table IN ('volunteers','tasks') AND public.has_role(auth.uid(),'coordonator_voluntari'))) THEN RAISE EXCEPTION 'Acces interzis'; END IF; IF char_length(_value)>200 OR _value IS NULL OR trim(_value)='' THEN RAISE EXCEPTION 'Valoare invalidă'; END IF; IF _field='branch_id' THEN IF NOT public.has_role(auth.uid(),'admin_national') AND _value::uuid IS DISTINCT FROM public.user_branch(auth.uid()) THEN RAISE EXCEPTION 'Poți atribui doar propria filială'; END IF; EXECUTE format('UPDATE public.%I SET branch_id=$1::uuid WHERE id=ANY($2)',_table) USING _value,_ids; ELSIF _field='tags' THEN EXECUTE 'UPDATE public.contacts SET tags=ARRAY(SELECT DISTINCT trim(x) FROM unnest(tags || string_to_array($1,'','')) x WHERE trim(x)<>'''') WHERE id=ANY($2)' USING _value,_ids; ELSE EXECUTE format('UPDATE public.%I SET status=$1 WHERE id=ANY($2)',_table) USING _value,_ids; END IF; GET DIAGNOSTICS n=ROW_COUNT; IF n<>(SELECT count(DISTINCT x) FROM unnest(_ids) x) THEN RAISE EXCEPTION 'Lotul include înregistrări fără acces; nimic nu a fost schimbat'; END IF; INSERT INTO public.audit_log(user_id,action,table_name) VALUES(auth.uid(),'BULK_'||upper(_field),_table); RETURN n; END; $$;
REVOKE ALL ON FUNCTION public.crm_bulk_change(text,uuid[],text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crm_bulk_change(text,uuid[],text,text) TO authenticated;
CREATE FUNCTION public.public_campaign_progress() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg jsonb; total numeric; n integer; BEGIN SELECT value INTO cfg FROM public.site_settings WHERE key='donation_campaign'; IF cfg IS NULL OR COALESCE((cfg->>'enabled')::boolean,false)=false THEN RETURN NULL; END IF; SELECT COALESCE(sum(amount),0),count(*) INTO total,n FROM public.donations WHERE status='confirmata' AND environment='live' AND currency='RON' AND paid_at >= (cfg->>'since')::timestamptz; RETURN jsonb_build_object('title',cfg->>'title','goal',(cfg->>'goal')::numeric,'since',cfg->>'since','total',total,'count',n,'impacts',cfg->'impacts'); END; $$;
REVOKE ALL ON FUNCTION public.public_campaign_progress() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_campaign_progress() TO anon,authenticated;
CREATE TRIGGER audit_contacts_changes AFTER UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION public.audit_row_change();